"""Authored trajectories, not a Cartesian paraphrase generator.

Each checkpoint explicitly specifies a decision profile and evidence available
at that point. Texts are synthetic examples for review, not customer guidance.
"""
from __future__ import annotations


def point(profile: str, text: str, evidence: str, **flags: bool) -> dict:
    return dict(profile=profile, text=text, evidence=evidence, flags=flags)


def variant(purpose: str, *points: dict) -> dict:
    return dict(purpose=purpose, checkpoints=list(points))


def sequence(purpose: str, *chunks: tuple[str, str, str]) -> dict:
    """Explicit authored chunks; concatenation only, no generated wording/labels."""
    accumulated = ""
    points = []
    for profile, chunk, evidence in chunks:
        accumulated += chunk
        points.append(point(profile, accumulated, evidence))
    return variant(purpose, *points)


def family(key: str, products: list[str], context: str, disclosure: bool,
           boundary: str, *variants: dict) -> dict:
    return dict(id=key, products=products, context=context,
                disclosure=disclosure, boundary=boundary, variants=list(variants))


